package coupons.repository;

import coupons.PlannedPurchase;
import java.sql.*;
import java.util.*;

/** PostgreSQL storage for intended purchase lines. */
public final class PostgresPlannedPurchaseRepository implements PlannedPurchaseRepository {
    private final PostgresConnectionFactory connections;
    public PostgresPlannedPurchaseRepository(PostgresConnectionFactory connections){this.connections=Objects.requireNonNull(connections);}
    @Override public void save(PlannedPurchase x,String actor){Objects.requireNonNull(x);PostgresRepositorySupport.requireActor(actor,"Recorded by");if(x.revision()!=1)throw new IllegalArgumentException("New purchase revision must be one.");PostgresRepositorySupport.transaction(connections,c->{ensurePlan(c,x.planId());try(PreparedStatement p=c.prepareStatement("INSERT INTO planned_purchase_current(purchase_id,plan_id,revision,payload) VALUES (?,?,?,?)")){p.setObject(1,x.plannedPurchaseId());p.setObject(2,x.planId());p.setLong(3,1);p.setBytes(4,PostgresRepositorySupport.serialize(x));p.executeUpdate();}catch(SQLException e){if("23505".equals(e.getSQLState()))throw new IllegalArgumentException("Planned purchase already exists.",e);throw e;}history(c,x,actor,"initial purchase");return null;});}
    @Override public Optional<PlannedPurchase> findById(UUID id){return findOne("purchase_id=?",Objects.requireNonNull(id));}
    @Override public List<PlannedPurchase> findByPlanId(UUID id){Objects.requireNonNull(id);return PostgresRepositorySupport.transaction(connections,c->{List<PlannedPurchase> out=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT payload FROM planned_purchase_current WHERE plan_id=? ORDER BY purchase_id")){p.setObject(1,id);try(ResultSet r=p.executeQuery()){while(r.next())out.add(PostgresRepositorySupport.deserialize(r.getBytes(1),PlannedPurchase.class));}}return List.copyOf(out);});}
    private Optional<PlannedPurchase> findOne(String where,UUID id){return PostgresRepositorySupport.transaction(connections,c->{try(PreparedStatement p=c.prepareStatement("SELECT payload FROM planned_purchase_current WHERE "+where)){p.setObject(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(PostgresRepositorySupport.deserialize(r.getBytes(1),PlannedPurchase.class)):Optional.empty();}}});}
    @Override public PlannedPurchase update(PlannedPurchase x,long expected,String actor,String reason){Objects.requireNonNull(x);PostgresRepositorySupport.requireActor(actor,"Changed by");PostgresRepositorySupport.requireActor(reason,"Reason");if(expected<1||x.revision()!=expected+1)throw new IllegalArgumentException("Invalid planned purchase revision.");return PostgresRepositorySupport.transaction(connections,c->{ensurePlan(c,x.planId());long stored;try(PreparedStatement p=c.prepareStatement("SELECT revision FROM planned_purchase_current WHERE purchase_id=? FOR UPDATE")){p.setObject(1,x.plannedPurchaseId());try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Planned purchase does not exist.");stored=r.getLong(1);}}if(stored!=expected)throw new ConcurrentModificationException("Planned purchase revision changed.");try(PreparedStatement p=c.prepareStatement("UPDATE planned_purchase_current SET plan_id=?,revision=?,payload=? WHERE purchase_id=?")){p.setObject(1,x.planId());p.setLong(2,x.revision());p.setBytes(3,PostgresRepositorySupport.serialize(x));p.setObject(4,x.plannedPurchaseId());p.executeUpdate();}history(c,x,actor,reason);return x;});}
    private static void ensurePlan(Connection c,UUID id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM shopping_plan_current WHERE plan_id=?")){p.setObject(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Shopping plan does not exist.");}}}
    private static void history(Connection c,PlannedPurchase x,String actor,String reason)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO planned_purchase_history(purchase_id,revision,changed_by,reason,payload) VALUES (?,?,?,?,?)")){p.setObject(1,x.plannedPurchaseId());p.setLong(2,x.revision());p.setString(3,actor);p.setString(4,reason);p.setBytes(5,PostgresRepositorySupport.serialize(x));p.executeUpdate();}}
}
